changeSet.sql:
ALTER TABLE department
  DROP CONSTRAINT IF EXISTS chk_department_parallel_capacity;

ALTER TABLE department
  ADD CONSTRAINT chk_department_parallel_capacity
    CHECK (
      parallel_capacity_enabled = false
        OR appointable IS NOT TRUE
        OR (
          parallel_capacity_enabled = true
            AND parallel_capacity_value IS NOT NULL
            AND parallel_capacity_value >= 1
        )
    );

